pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != c.owner());
        vm.prank(nonOwner);
        try c.setOwner(newOwner) returns (bool) {
            assertEq(c.owner(), c.owner());
        } catch {
        }
        assertTrue(c.owner() != newOwner || nonOwner == c.owner(), "non-owner changed owner");
    }
}
